#include <iostream>
#include <string>
#include <uvm>

using namespace uvm;

// uvm_config_db::exists() must resolve the scope the same way as get():
// a null context means the instance name is the complete scope.

static void check(const std::string& what, uvm_component* cntxt,
                  const std::string& inst_name, const std::string& field_name)
{
  int value = 0;
  bool got = uvm_config_db<int>::get(cntxt, inst_name, field_name, value);
  bool found = uvm_config_db<int>::exists(cntxt, inst_name, field_name);

  std::cout << what << ": get=" << std::boolalpha << got
            << " exists=" << found << std::endl;
}

int sc_main (int argc, char** argv)
{
  uvm_component* top = new uvm_component("top", nullptr);
  uvm_component* env = new uvm_component("env", top);

  uvm_config_db<int>::set(nullptr, "top.env", "field", 5);

  check("root context, full path", nullptr, "top.env", "field");
  check("root context, explicit", uvm_root::get(), "top.env", "field");
  check("parent context, relative path", top, "env", "field");
  check("own context, empty path", env, "", "field");
  check("root context, wrong path", nullptr, "top.other", "field");
  check("root context, wrong field", nullptr, "top.env", "other");

  return 0;
}
EOF
